"""Render a stable report and a compact public checksum manifest from study output."""
import argparse,json
from pathlib import Path

def main():
    p=argparse.ArgumentParser();p.add_argument('input');p.add_argument('--out',default='STRATEGY_COMPARISON_2026_11_05.md');p.add_argument('--manifest',default='research/strategy_manifest.json');a=p.parse_args()
    d=json.loads(Path(a.input).read_text());r=d['results'];symbols=['BTCUSDT','ETHUSDT','SOLUSDT'];names=['current','trend','breakout','reversion','hold','none']
    Path(a.manifest).write_text(json.dumps({'created_utc':d['created_utc'],'quality':d['quality'],'files':d['manifest']},indent=2,ensure_ascii=False)+'\n',encoding='utf8')
    summary={key:{k:v for k,v in value.items() if k!='trade_pnls'} for key,value in r.items()}
    Path('research/strategy_results_summary.json').write_text(json.dumps(summary,indent=2,ensure_ascii=False)+'\n',encoding='utf8')
    lines=['# Сравнение стратегий Spot paper — 5 ноября 2026','',
    '## Решение','',
    'В рамках заранее заданного фильтра кандидата для prospective-наблюдения нет. Все четыре активных правила убыточны после базовых издержек в финальном 2025 году на каждом из трёх активов. Это результат данной модели и данных, а не доказательство невозможности прибыльной стратегии. Стратегии на VM не изменялись и не активировались.','',
    'План и отклонение из-за разрыва данных зафиксированы в [плане](STRATEGY_RESEARCH_PLAN.md) до вычисления результатов. 2023 год после разрыва использован для прогрева, 2024 — проверка, 2025 — отложенный период.','',
    '## Действующие правила по коду','',
    '`signal_details` вычисляет пересечение SMA10 и SMA30 на закрытых свечах: BUY на пересечении вверх, SELL вниз, иначе HOLD. Spot при новой свече открывает long только на BUY и закрывает по SELL, stop или take; стандартные аргументы — 15m, до 10 USDT, stop 2%, take 4%. Размер и защитные пороги являются настройками запуска, а не сигналом. После выхода нового входа на старом сигнале нет.','',
    'Isolated futures при пересечении открывает LONG/SHORT; обратный сигнал закрывает позицию, возможный обратный вход — со следующей свечи при согласованном тренде. Кодовые defaults — маржа 10 USDT, плечо 1×, 15m; есть stop 2%, take 4%, funding и модельная ликвидация. Cross futures и Spot margin используют тот же сигнал для LONG/SHORT, в коде стратегии — по 5 USDT маржи/собственных средств на вход, stop 2%, take 4%; при противоположном сигнале их текущие позиции автоматически не закрываются. Плечо задаётся сохранёнными настройками: cross до 10×, margin до 3×. Для margin дополнительно действуют долг, проценты и ограничения залога. Фактические настройки могут отличаться от defaults.','',
    'Ликвидация, stop/take, проверка свежести, funding/долга, резервов и пауза — защитные и финансовые ограничения, а не индикатор входа. Результаты ниже моделируют приближение Spot, а не защитные механизмы или execution всех четырёх процессов.','',
    'Архивы Binance Spot 15m, BTCUSDT/ETHUSDT/SOLUSDT; SHA-256 и адреса в [манифесте](research/strategy_manifest.json). Получено: '+d['created_utc']+'. Непрерывность с 25.03.2023 до 31.12.2025 включительно проверена по каждому активу, включая время завершения, дубли и OHLC. 24.03.2023 досрочная свеча и пять пропусков, участок исключён. Данные с 2025 года преобразованы из микросекунд.','',
    'В таблицах каждая ячейка — независимый счёт на 1000 USDT, размер сделки до 10 USDT, без плеча. Значение net включает модельную стоимость закрытия остатка в конце периода; это оценка по последнему close, а не доказательство исполнения. Просадка считается по 15-минутным close и может занижать внутрисвечную. Время восстановления — максимальное время от начала просадки до возврата к предыдущему максимуму или до конца периода; звёздочка означает, что на конец периода счёт находится в просадке.','',
    '## Отложенный период 2025','',
    '| Правило | Актив | Net, USDT | Net: повышенные издержки | Сделок | Оборот USDT | В позиции, % | Средняя сделка USDT | Просадка, % | Восстановление, часы |',
    '|---|---|---:|---:|---:|---:|---:|---:|---:|---:|']
    for name in names:
        for symbol in symbols:
            x=r[f'{symbol}|2025|{name}|base'];e=r[f'{symbol}|2025|{name}|expensive'];avg='—' if x['avg_trade'] is None else f"{x['avg_trade']:.4f}";recovery=f"{x['max_recovery_hours']:.1f}"+('*' if x['open_drawdown_at_end'] else '')
            lines.append(f"| {name} | {symbol} | {x['net']:.4f} | {e['net']:.4f} | {x['trades']} | {x['turnover']:.2f} | {x['exposure_pct']:.2f} | {avg} | {x['max_dd_pct']:.3f} | {recovery} |")
    lines+=['','Показатель без лучшей сделки — сумма трёх независимых результатов за вычетом лучшей отдельной сделки; без лучшего актива — сумма двух худших результатов. Сумма используется для стресс-проверки, а не как доходность одного счёта.','',
    '| Правило | Сумма net трёх счетов | Без лучшей сделки | Без лучшего актива | Сделок в up / net | Сделок в down / net |', '|---|---:|---:|---:|---:|---:|']
    for name in names:
        xs=[r[f'{s}|2025|{name}|base'] for s in symbols];net=sum(x['net'] for x in xs);pnls=[p for x in xs for p in x['trade_pnls']];best=max(pnls,default=0)
        upn=sum(x['regimes']['up']['trades'] for x in xs);up=sum(x['regimes']['up']['net'] for x in xs);dn=sum(x['regimes']['down']['trades'] for x in xs);down=sum(x['regimes']['down']['net'] for x in xs)
        lines.append(f"| {name} | {net:.4f} | {net-best:.4f} | {net-max(x['net'] for x in xs):.4f} | {upn} / {up:.4f} | {dn} / {down:.4f} |")
    lines+=['','Режим — прошлый дневной close относительно SMA30 предыдущих закрытых дней на момент входа; режим не является прогнозом.','',
    '## Проверка 2024: net после базовых издержек, USDT','', '| Правило | BTC | ETH | SOL |', '|---|---:|---:|---:|']
    for name in names:
        xs=[r[f'{s}|2024|{name}|base']['net'] for s in symbols];lines.append('| '+name+' | '+' | '.join(f'{x:.4f}' for x in xs)+' |')
    ambiguous=sum(r[f'{s}|{y}|{n}|base']['ambiguous'] for s in symbols for y in (2024,2025) for n in names)
    lines+=['',f'Одновременных касаний stop и take в смоделированных позициях: {ambiguous}; вариант take-first дал тот же результат. При gap стоп исполняется по более плохому открытию. Доходность buy-and-hold показана с аналогичным лимитом позиции 10 USDT, а не с вложением всего счёта.','',
    '## Издержки и ограничения','',
    'На входе и выходе: 0,10% комиссии, 0,02% половины spread и 0,03% slippage; стресс: 0,10% + 0,04% + 0,06%. Комиссия — стандартная ставка по опубликованной таблице Binance, spread/slippage — сценарные допущения, а не измеренные сделки. Количество округляется вниз по фиксированным шагам BTC 0,00001, ETH 0,0001, SOL 0,001; модельный минимум 5 USDT. Исторические значения биржевых фильтров не подтверждены. Непосредственное исполнение на следующем открытии и свечной stop/take не моделируют задержку, глубину, отсутствие ликвидности или частичные исполнения. Результаты не являются точной реконструкцией приложения, которое использует актуальные котировки и свою обработку заявок.','',
    'Только Spot. Из этих чисел нельзя делать выводы о perpetual futures или margin: funding, котировки mark, ликвидация, ограничения займа и исторические проценты не смоделированы. Промежуток 2023 с разрывом не подменялся. Набор из трёх активов и одного финального года не исключает переобучения, изменения режимов и selection bias.','',
    '## Решение по правилам и будущему наблюдению','',
    'Отклонить все четыре как кандидатов на включение по этим критериям: current и breakout несут значительные потери при большом обороте, reversion ещё слабее, trend ближе к нулю, но отрицателен на всех трёх активах и при повышенных издержках. Отсутствие торговли сохраняет капитал; buy-and-hold — ориентир с рыночным риском, а не торговая рекомендация. При таких данных не выбираем победителя и не предлагаем включать какие-либо входы.','',
    'Если отдельное последующее исследование даст положительный зафиксированный кандидат и владелец отдельно разрешит запуск, prospective-протокол: только paper, те же три актива и правила без настройки, до 10 виртуальных USDT на позицию, без плеча; не менее 12 месяцев и 100 закрытых сделок кандидата, с продолжением до достижения обоих условий. Немедленная остановка новых входов при ошибке источника/учёта, утрате защиты или просадке счёта 5%; пауза с ручным разбором, без изменения параметров по текущим результатам. Цель — проверка воспроизводимости, не подтверждение прибыльности.','',
    'Воспроизведение: `PYTHONPATH=. python3 -B research/strategy_study.py --data /путь/вне/git --output /путь/results.json`, затем `python3 research/write_strategy_report.py /путь/results.json`. Архивы сверяются с опубликованными CHECKSUM; их следует хранить вне Git. Тесты: `PYTHONPATH=. python3 -B -m unittest tests.test_strategy_research -q`. Источники: [Binance Public Data](https://github.com/binance/binance-public-data), [комиссии Binance](https://www.binance.com/en/fee/trading).']
    Path(a.out).write_text('\n'.join(lines)+'\n',encoding='utf8')
if __name__=='__main__':main()
